# ============================================================
# SaleHop sign tweak -- landscape by default, arrow tip text removed
# ============================================================
#
# Two small changes to the printable sign (from the last update):
#
#   - The sign now opens in Landscape by default instead of Portrait
#     (you can still switch back to Portrait with the toggle).
#   - The "Tip: circle or trace an arrow above with a marker to point
#     the way." line under the arrow is gone -- just the arrow itself
#     now.
#
# Only one file changes this time: app/listing/[id]/sign/SignBuilder.js
#
# Run this from inside your salehop project folder (where package.json
# lives) -- same as every script before this one.

# ---------- Safety check: are we actually in the right folder? ----------
if (-not (Test-Path "package.json")) {
  Write-Host ""
  Write-Host "STOP: There's no package.json in this folder." -ForegroundColor Red
  Write-Host "You need to 'cd' into your actual salehop project folder first," -ForegroundColor Red
  Write-Host "then run this script again from there." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
if (-not (Test-Path ".git")) {
  Write-Host ""
  Write-Host "STOP: This folder has package.json but no .git folder," -ForegroundColor Red
  Write-Host "so it isn't connected to your GitHub/Vercel project." -ForegroundColor Red
  Write-Host "Make sure you're in the folder you originally cloned, not a copy." -ForegroundColor Red
  Write-Host ""
  Write-Host "Current folder: $PWD" -ForegroundColor Yellow
  exit 1
}
Write-Host "Found package.json and .git here -- this looks like the right folder." -ForegroundColor Cyan
Write-Host ""

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)
Write-Host ""

# ---------- app/listing/[id]/sign/SignBuilder.js ----------
[System.IO.Directory]::CreateDirectory("app/listing/[id]/sign") | Out-Null
$b64_SignBuilder_js = @"

"@
[System.IO.File]::WriteAllBytes("app/listing/[id]/sign/SignBuilder.js", [Convert]::FromBase64String($b64_SignBuilder_js))
Write-Host "Wrote app/listing/[id]/sign/SignBuilder.js" -ForegroundColor Green
Write-Host ""

# ---------- Verify it actually got written ----------
# Test-Path -LiteralPath (not plain Test-Path) because the [id] folder
# name would otherwise be treated as a wildcard pattern by PowerShell.
if (-not (Test-Path -LiteralPath "app/listing/[id]/sign/SignBuilder.js")) {
  Write-Host ""
  Write-Host "STOP: app/listing/[id]/sign/SignBuilder.js did not get written." -ForegroundColor Red
  Write-Host "Nothing was committed. Please re-run this script from the correct folder." -ForegroundColor Red
  exit 1
}
Write-Host "File verified on disk." -ForegroundColor Green
Write-Host ""

Write-Host "File written. Reviewing git status..." -ForegroundColor Cyan
git status

$commit = Read-Host "Type Y and press Enter to commit and push this change (or anything else to stop here)"
if ($commit -eq "Y" -or $commit -eq "y") {
  git add -A
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git add failed -- see the error above. Nothing was committed or pushed." -ForegroundColor Red
    exit 1
  }

  git commit -m "Default sign to landscape and remove the arrow tip text"
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git commit failed -- see the error above (this also happens if there was nothing new to commit). Nothing was pushed." -ForegroundColor Red
    exit 1
  }

  git push
  if ($LASTEXITCODE -ne 0) {
    Write-Host "git push failed -- see the error above. Your changes are committed locally but NOT on GitHub/Vercel yet." -ForegroundColor Red
    exit 1
  }

  Write-Host ""
  Write-Host "Pushed successfully! Vercel should pick this up and deploy automatically." -ForegroundColor Green
} else {
  Write-Host "Stopped before committing. Your file is updated locally -- run git add -A, git commit, git push whenever you are ready." -ForegroundColor Yellow
}
